const M=require('../../js/model');
const state=(id,actorId,time,q)=>({id,actorId,time,name:id,...(q!==undefined?{simulation:{q}}:{})});
const task=(id,fromStateId,toStateId,simulation={enabled:false})=>({id,fromStateId,toStateId,label:id,simulation});
const link=(id,source,target,duration=0,qualityRetention=1)=>({id,label:id,source:{type:'state',id:source},target:typeof target==='string'?{type:'state',id:target}:target,propagation:{duration,qualityRetention},simulation:{enabled:true}});
const cdf=(points)=>({type:'cdf',qualityInput:'q',curves:[{q:1,points}]});
function base(){return M.defaults({version:3,title:'quality',time:{unit:'seconds',duration:100,snap:1},actors:[{id:'a',name:'A',side:'friendly'},{id:'b',name:'B',side:'friendly'},{id:'e',name:'E',side:'hostile'}],states:[state('s0','a',0,.8),state('s1','a',10),state('r0','b',10),state('r1','b',20)],tasks:[task('produce','s0','s1',{enabled:false,qualityRetention:.75}),task('consume','r0','r1',{enabled:false,qualityRetention:.8})],causalLinks:[link('report','s1','r0',0,.5)],simulation:{successStateIds:['r1'],iterations:16,seed:17,deadline:30}});}
function gate(){const d=M.defaults({version:3,title:'gate',time:{unit:'seconds',duration:100,snap:1},actors:[{id:'a',name:'A',side:'friendly'},{id:'e',name:'E',side:'hostile'}],states:[state('launch','e',10,.1),state('condition','e',15,.1),state('end','e',30),state('killed','e',21),state('prepare','a',0,.8),state('effect','a',20)],tasks:[task('flight','launch','end',{enabled:false,waitForStateIds:['condition']}),task('action','prepare','effect',{enabled:true,performanceModel:cdf([{t:0,p:0,q:1},{t:20,p:1,q:1}])})],causalLinks:[link('hit','effect',{type:'junction',taskId:'flight',id:'point',outcomeStateId:'killed'},1)],simulation:{successStateIds:['killed'],iterations:16,seed:3}});d.tasks[0].junctions=[{id:'point',time:21,outcomes:[{label:'destroyed',toStateId:'killed',delay:0}],simulation:{mode:'effect'}}];return d;}
const trial=(d,u=.5)=>require('../../js/simulation').trial(require('../../js/simulation').compile(d),()=>u);
module.exports={state,task,link,cdf,base,gate,trial};
